import java.io.InputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.PriorityQueue;

public class Main {

    static class Edge {
        int to;
        int weight;
        int id;

        Edge(int to, int weight, int id) {
            this.to = to;
            this.weight = weight;
            this.id = id;
        }
    }

    static class Cycle {
        int length;

        Cycle(int length) {
            this.length = length;
        }
    }

    static ArrayList<Edge>[] adj;
    static int[] depth;
    static int[] parentNode;
    static int[] parentWeight;
    static int[] parentEdgeId;
    static boolean[] visited;
    static Cycle[] vertexCycle;

    static void findCycles(int u, int p, int edgeId, int d) {
        visited[u] = true;
        depth[u] = d;

        for (Edge e : adj[u]) {
            if (e.id == edgeId) continue;
            int v = e.to;
            if (visited[v]) {
                if (depth[v] < depth[u]) {
                    // Back-edge encontrada: ciclo de v até u
                    int len = e.weight;
                    ArrayList<Integer> cycleVertices = new ArrayList<>();
                    int curr = u;
                    while (curr != v) {
                        cycleVertices.add(curr);
                        len += parentWeight[curr];
                        curr = parentNode[curr];
                    }
                    cycleVertices.add(v);

                    Cycle cycle = new Cycle(len);
                    for (int node : cycleVertices) {
                        vertexCycle[node] = cycle;
                    }
                }
            } else {
                parentNode[v] = u;
                parentWeight[v] = e.weight;
                parentEdgeId[v] = e.id;
                findCycles(v, u, e.id, d + 1);
            }
        }
    }

    static class State implements Comparable<State> {
        int u;
        long dist;

        State(int u, long dist) {
            this.u = u;
            this.dist = dist;
        }

        @Override
        public int compareTo(State o) {
            return Long.compare(this.dist, o.dist);
        }
    }

    static final long INF = Long.MAX_VALUE / 4;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        int E = scanner.nextInt();
        if (E == -1) return;
        int R = scanner.nextInt();

        adj = new ArrayList[E + 1];
        for (int i = 1; i <= E; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 0; i < R; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int w = scanner.nextInt();
            adj[u].add(new Edge(v, w, i));
            adj[v].add(new Edge(u, w, i));
        }

        depth = new int[E + 1];
        parentNode = new int[E + 1];
        parentWeight = new int[E + 1];
        parentEdgeId = new int[E + 1];
        visited = new boolean[E + 1];
        vertexCycle = new Cycle[E + 1];

        for (int i = 1; i <= E; i++) {
            if (!visited[i]) {
                findCycles(i, 0, -1, 1);
            }
        }

        int K = scanner.nextInt();
        long[] dist = new long[E + 1];
        StringBuilder sb = new StringBuilder();

        for (int k = 0; k < K; k++) {
            int X = scanner.nextInt();
            int T = scanner.nextInt();

            Arrays.fill(dist, INF);
            dist[X] = 0;

            PriorityQueue<State> pq = new PriorityQueue<>();
            pq.add(new State(X, 0));

            long best = INF;

            while (!pq.isEmpty()) {
                State curr = pq.poll();
                int u = curr.u;
                long d = curr.dist;

                if (d > dist[u]) continue;

                if (2 * d >= best) {
                    break;
                }

                if (vertexCycle[u] != null && vertexCycle[u].length >= T) {
                    long total = 2 * d + vertexCycle[u].length;
                    if (total < best) {
                        best = total;
                    }
                }

                for (Edge e : adj[u]) {
                    if (dist[e.to] > d + e.weight) {
                        dist[e.to] = d + e.weight;
                        pq.add(new State(e.to, dist[e.to]));
                    }
                }
            }

            if (best >= INF) {
                sb.append("-1\n");
            } else {
                sb.append(best).append("\n");
            }
        }

        System.out.print(sb);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= 32 && c != -1) {
                c = read();
            }
            if (c == -1) return -1;
            int res = 0;
            while (c > 32) {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + c - '0';
                }
                c = read();
            }
            return res;
        }
    }
}
